package dk.jamesbabz.madkursus.outbound.recipe.details;
import java.math.BigDecimal;import java.util.UUID;import jakarta.persistence.*;import lombok.*;import dk.jamesbabz.madkursus.service.models.RecipeUnit;
@Entity @Table(name="recipe_prepared_component_ingredients") @Getter @NoArgsConstructor(access=AccessLevel.PROTECTED)
public class RecipePreparedComponentIngredientEntity{@Id private UUID id;@ManyToOne(optional=false)@JoinColumn(name="prepared_component_id")private RecipePreparedComponentEntity component;@ManyToOne(optional=false)@JoinColumn(name="recipe_ingredient_id")private RecipeIngredientEntity recipeIngredient;private BigDecimal quantity;@Enumerated(EnumType.STRING)private RecipeUnit unit;private int sortOrder;public RecipePreparedComponentIngredientEntity(UUID id,RecipeIngredientEntity ingredient,BigDecimal quantity,RecipeUnit unit,int order){this.id=id;this.recipeIngredient=ingredient;this.quantity=quantity;this.unit=unit;this.sortOrder=order;}void setComponent(RecipePreparedComponentEntity v){component=v;}}
